// ROUTER RESI — DETERMINISTIK. Berjalan SEBELUM AI Agent, tanpa LLM.
// Tugas: deteksi pola nomor resi di pesan user, cek statusnya LANGSUNG di
// sini (bukan atas kemauan Agent), lalu suntikkan hasilnya sebagai blok
// [DATA FAKTUAL SISTEM] ke pesan yang diteruskan ke Agent.
//
// MOCK: mockShipmentStatus() adalah replika logika node tool
// get_shipment_status (lihat mock/mock-tools.json). Saat API/MCP asli
// tersedia, ganti fungsi ini DAN tool-nya dengan panggilan endpoint asli
// yang sama — kontrak datanya jangan berubah.
//
// Pola resi: token 8-20 karakter alfanumerik yang mengandung huruf DAN
// angka (nomor HP murni angka sengaja dikecualikan). Maksimal 3 resi/pesan.
//
// GERBANG NIAT (v2.1): Router juga menilai apakah pesan butuh blok SOP
// (_needsSop). Blok kutipan hanya dicari & ditempel untuk pertanyaan
// berindikasi SOP/FAQ — pertanyaan status murni dan pertanyaan tentang
// percakapan tidak menerimanya (temuan Putaran 2: latensi + kontaminasi).

function mockShipmentStatus(resi) {
  return {
    tracking_number: resi,
    courier: "DUMMY-REG",
    current_status: "IN_TRANSIT",
    last_location: "Hub Jakarta Timur (DUMMY)",
    updated_at: "2026-11-17T08:15:00+07:00", // TETAP dari data dummy (v2.1), bukan jam berjalan
    history: [
      { timestamp: "2026-11-17T08:15:00+07:00", location: "Hub Jakarta Timur (DUMMY)", status: "IN_TRANSIT" },
      { timestamp: "2026-11-16T19:40:00+07:00", location: "Drop Point Bandung (DUMMY)", status: "PICKED_UP" }
    ]
  };
}

const item = $input.first().json;
const original = item.chatInput || '';

const tokens = (original.match(/[A-Za-z0-9]{8,20}/g) || [])
  .map(s => s.toUpperCase())
  .filter(s => /[0-9]/.test(s) && /[A-Z]/.test(s));
const resis = [...new Set(tokens)].slice(0, 3);

const preChecked = resis.map(r => {
  const d = mockShipmentStatus(r);
  return { resi: r, status: d.current_status, location: d.last_location, updated_at: d.updated_at, courier: d.courier };
});

// GERBANG NIAT SOP — deterministik, regex kata kunci (tanpa LLM).
const _q = original.toLowerCase();
const _memoryIntent = /(tadi|sebelumnya|pertama|riwayat|percakapan)/.test(_q);
const _procedureIntent = /(ngapain|gimana|bagaimana|prosedur|solusi|langkah|eskalasi|harus|kenapa|kok|gagal|rusak|hilang|terlambat|telat|stuck|nyangkut|tercecer|cut-off|cutoff|ongkir|sla|aturan|kebijakan|syarat|estimasi)/.test(_q);
const _knowledgeQuestion = !preChecked.length && !_memoryIntent && /(\?|apa|berapa|kapan|jam|apakah|boleh)/.test(_q);
const needsSop = !_memoryIntent && (_procedureIntent || _knowledgeQuestion);

let chatInput = original;
if (preChecked.length) {
  const lines = preChecked.map(p =>
    `- Resi ${p.resi}: status ${p.status}; lokasi terakhir ${p.location}; diperbarui ${p.updated_at}; kurir ${p.courier}.`
  ).join('\n');
  chatInput = original +
    `\n\n[DATA FAKTUAL SISTEM — SUDAH DICEK OTOMATIS]\n${lines}\nGunakan data ini persis untuk resi di atas; jangan panggil get_shipment_status lagi untuk resi tersebut.`;
}

return [{ json: {
  chatInput,
  sessionId: item.sessionId,
  _originalInput: original,
  _preChecked: preChecked,
  _needsSop: needsSop
} }];

// VALIDATOR JAWABAN v1.3 — GUARDRAIL SADAR-KLAIM + MODE AUGMENT. Berjalan SETELAH Agent.
// Perbaikan dari v1.1 (temuan uji A1 Guarded v2): cek lokasi v1.1 menembak
// frasa generik SOP "HUB terdekat" seolah itu klaim lokasi, dan membuang
// jawaban Agent yang sebenarnya benar. Kini klaim lokasi hanya diakui bila
// menyebut nama tempat dari daftar kota/area yang dikenal (gazetteer);
// frasa generik ("HUB terdekat", "HUB tujuan") diabaikan. Aturan penghindar
// juga dipersempit: hanya untuk pertanyaan status MURNI (tanpa kata kendala).
// v1.3 menambah MODE AUGMENT (temuan B1 Guarded v2): jawaban lolos yang
// menghilangkan resi yang sudah dicek sama sekali TIDAK dibuang — baris
// status deterministik ditempelkan di depannya. Penggantian penuh kini
// hanya untuk kontradiksi dan penghindaran pertanyaan status murni.

const router = $('Router Resi (Deterministik)').first().json;
const pre = router._preChecked || [];
const item = $input.first().json;
const answer = item.output || '';
const sessionId = item.sessionId || router.sessionId;

if (!pre.length) {
  return [{ json: { output: answer, sessionId } }];
}

const KNOWN_STATUS = ['IN_TRANSIT','DELIVERED','PICKED_UP','OUT_FOR_DELIVERY','ON_DELIVERY','FAILED_DELIVERY','RETURNED'];
const PLACES = ['jakarta','bandung','surabaya','medan','semarang','yogyakarta','jogja','makassar','palembang','denpasar','balikpapan','pontianak','manado','padang','pekanbaru','batam','bogor','depok','tangerang','bekasi','malang','solo','cirebon','lampung','jambi','aceh','kupang','ambon','jayapura','banjarmasin','samarinda','timur','barat','utara','selatan','pusat'];
const upper = answer.toUpperCase();
let fail = false;

for (const p of pre) {
  const claims = KNOWN_STATUS.filter(s => upper.includes(s));
  // Menyatakan status, tapi bukan status dari sistem -> karangan/kontradiksi
  if (claims.length && !claims.includes(p.status)) fail = true;
  // Klaim lokasi spesifik (menyebut nama tempat) yang bertentangan dengan sistem
  if (claims.includes(p.status)) {
    const mentions = [...answer.matchAll(/Hub\s+[A-Za-z]+(?:\s+[A-Za-z]+)?/gi)].map(m => m[0].toLowerCase());
    const sysLoc = p.location.toLowerCase();
    for (const h of mentions) {
      const isSpecific = PLACES.some(pl => new RegExp(`\\b${pl}\\b`).test(h));
      if (isSpecific && !sysLoc.includes(h)) fail = true;
    }
  }
}

// Pertanyaan status MURNI yang dijawab TANPA klaim status apa pun = menghindar.
// Kata kendala/penjelasan (gagal, rusak, kok, kenapa, dsb.) mengecualikan aturan ini.
const q = (router._originalInput || '').toLowerCase();
const procedureIntent = /(ngapain|gimana|prosedur|solusi|langkah|eskalasi)/.test(q);
const kendalaIntent = /(gagal|rusak|hilang|terlambat|stuck|nyangkut|kok|kenapa|tercecer|telat)/.test(q);
const statusIntent = /(cek|status|sampai|posisi|di mana|dimana|berada|gerak)/.test(q);
if (!fail && statusIntent && !procedureIntent && !kendalaIntent) {
  const answered = pre.some(p => upper.includes(p.resi) && upper.includes(p.status));
  if (!answered) fail = true;
}

if (!fail) {
  // MODE AUGMENT: bila tidak satu pun resi yang sudah dicek tercakup
  // (nomor resi + statusnya) di jawaban, tempelkan baris status
  // deterministik di depan jawaban — jangan buang isinya.
  const covered = pre.some(p => upper.includes(p.resi) && upper.includes(p.status));
  if (!covered) {
    const head = pre.map(p =>
      `Status dari sistem: Resi ${p.resi} — ${p.status}, lokasi terakhir ${p.location}, diperbarui ${p.updated_at}.`
    ).join('\n');
    return [{ json: { output: head + '\n\n' + answer, sessionId } }];
  }
  return [{ json: { output: answer, sessionId } }];
}

const nowWib = new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' });
const lines = pre.map(p =>
  `Resi ${p.resi}: status ${p.status}, lokasi terakhir ${p.location}, diperbarui ${p.updated_at}.`
).join('\n');
const fallback = lines +
  `\n\nSumber: sistem (pengecekan otomatis), data per ${nowWib} WIB` +
  `\n\n(Catatan sistem: jawaban asisten tidak lolos validasi untuk resi di atas, sehingga diganti ringkasan data sistem.)`;

return [{ json: { output: fallback, sessionId } }];

// SUSUN BLOK SOP — menggabungkan output Router dengan hasil pencarian Qdrant
// yang dilakukan workflow (Router v2), lalu menempelkan blok
// [KUTIPAN SOP/FAQ DARI SISTEM] ke pesan untuk Agent.
// Hanya chunk dengan skor >= 0.45 yang ditempel; di bawah itu dianggap tidak
// cukup relevan (blok tetap disertakan sebagai penanda 'tidak ditemukan').
// v2.1: bila Router menilai pesan tidak butuh SOP (_needsSop=false), node
// ini tidak menempelkan blok apa pun.

const router = $('Router Resi (Deterministik)').first().json;
const hits = ($input.first().json.result || []);
const SCORE_MIN = 0.45;

const chunks = hits
  .filter(h => (h.score ?? 0) >= SCORE_MIN)
  .map(h => {
    const p = h.payload || {};
    const text = (p.pageContent || p.content || p.text || '').trim();
    const src = p.metadata && p.metadata.source_file ? ` [sumber file: ${p.metadata.source_file}]` : '';
    return text ? text + src : '';
  })
  .filter(Boolean);

let chatInput = router.chatInput;
const needsSop = router._needsSop !== false;
if (!needsSop) {
  // Gerbang niat Router menutup jalur SOP untuk pertanyaan ini: jangan
  // tempel blok apa pun (hemat konteks Agent + cegah kontaminasi).
} else if (chunks.length) {
  chatInput += `\n\n[KUTIPAN SOP/FAQ DARI SISTEM — SUDAH DICARI OTOMATIS]\n` +
    chunks.map((c, i) => `(${i + 1}) ${c}`).join('\n\n') +
    `\nGunakan kutipan ini sebagai sumber jawaban SOP/FAQ-mu dan kutip penanda yang tertulis di dalamnya.`;
} else {
  chatInput += `\n\n[KUTIPAN SOP/FAQ DARI SISTEM] Tidak ditemukan kutipan yang cukup relevan untuk pertanyaan ini.`;
}

return [{ json: {
  chatInput,
  sessionId: router.sessionId,
  _originalInput: router._originalInput,
  _preChecked: router._preChecked,
  _needsSop: needsSop,
  _sopChunks: needsSop ? chunks.length : 0
} }];
